const categoryLabels={breakfast:'ЗАВТРАК',main:'ОБЕД / УЖИН',snack:'ПЕРЕКУС'};
function addToBasket(items){const b=read(STORE.basket,{});items.forEach(item=>{const clean=String(item).trim();if(clean&&!b[clean])b[clean]={qty:1,checked:false}});write(STORE.basket,b);renderBasket();updateBasketBadge()}
function updateBasketBadge(){const b=read(STORE.basket,{});const n=Object.keys(b).length;$$('[data-basket-count]').forEach(el=>el.textContent=n)}

// Recipe catalogue and one-click matching.
const grid=$('#recipe-grid'),modal=$('#recipe-modal');let activeIngredients=[];
function renderRecipeCards(){if(!grid)return;grid.innerHTML=recipes.map((r,i)=>`<article class="recipe-card" data-category="${r.kind}${r.noCook?' no-cook':''}" data-name="${safeText((r.title+' '+r.short+' '+r.items.join(' ')).toLowerCase())}"><div class="recipe-art ${['art-oats','art-bowl','art-sandwich','art-beans','art-eggs','art-yogurt'][i%6]}"><span>${String(i+1).padStart(2,'0')} / ${r.time} МИН</span><div class="food-emoji">${['🥣','🍲','🥪','🥗','🍳','🍎','🐟','🍗','🥔','🍜','🍚','🍝','🍏','🫐'][i%14]}</div><i>${r.time}′</i></div><div class="recipe-info"><div class="recipe-meta"><span>${categoryLabels[r.kind]}</span><span>${r.noCook?'БЕЗ ГОТОВКИ':r.cheap?'БЮДЖЕТНО':'ПРОСТО'}</span></div><h3>${safeText(r.title)}</h3><p>${safeText(r.short)}</p><button class="recipe-open" data-recipe="${r.id}">СМОТРЕТЬ РЕЦЕПТ <span>↗</span></button></div></article>`).join('');$$('[data-recipe]',grid).forEach(btn=>btn.addEventListener('click',()=>openRecipe(btn.dataset.recipe)));}
function openRecipe(id){const r=recipes.find(x=>x.id===id);if(!r||!modal)return;activeIngredients=r.items;$('#modal-title').textContent=r.title;$('#modal-desc').textContent=r.short;$('#modal-ingredients').innerHTML=r.ingredients.map(x=>'<li>'+safeText(x)+'</li>').join('');$('#modal-steps').innerHTML=r.steps.map(x=>'<li>'+safeText(x)+'</li>').join('');$('#modal-warning').textContent=r.note||'';modal.classList.add('open');modal.setAttribute('aria-hidden','false')}
if(grid)renderRecipeCards();
if(modal){const close=()=>{modal.classList.remove('open');modal.setAttribute('aria-hidden','true')};$('.modal-close',modal).addEventListener('click',close);modal.addEventListener('click',e=>{if(e.target===modal)close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});$('#modal-add').addEventListener('click',()=>{addToBasket(activeIngredients);const b=$('#modal-add');b.textContent='ДОБАВЛЕНО В КОРЗИНУ ✓';setTimeout(()=>{b.textContent='Добавить ингредиенты в корзину ↗'},1400)})}
$$('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{$$('[data-filter]').forEach(b=>b.classList.toggle('selected',b===btn));filterRecipes()}));
const search=$('#recipe-search');if(search)search.addEventListener('input',filterRecipes);
function filterRecipes(){const filter=$('.filter-chip.selected')?.dataset.filter||'all',term=(search?.value||'').trim().toLowerCase();$$('.recipe-card').forEach(card=>{const cats=card.dataset.category.split(' ');card.hidden=!(filter==='all'||cats.includes(filter))||!((card.dataset.name+' '+card.textContent).toLowerCase().includes(term))})}
function chooseRecipe(){const profile=$('#food-profile')?.value||'everyday',maxTime=Number($('#max-time')?.value||30),kitchen=$('#kitchen-type')?.value||'any',budget=!!$('#budget-mode')?.checked,excluded=($('#exclude-ingredients')?.value||'').toLowerCase().split(/[,;]+/).map(x=>x.trim()).filter(Boolean);let pool=recipes.filter(r=>r.time<=maxTime&&(!budget||r.cheap)&&(kitchen!=='no-cook'||r.noCook));if(profile==='lactose')pool=pool.filter(r=>!r.dairy);if(profile==='gluten')pool=pool.filter(r=>!r.gluten);if(profile==='vegetarian')pool=pool.filter(r=>r.vegetarian);if(profile==='vegan')pool=pool.filter(r=>r.vegetarian&&!r.dairy&&!/яйц|омлет|сэндвич с яйц|творог|йогурт/i.test(r.title+' '+r.items.join(' '))); if(excluded.length)pool=pool.filter(r=>!excluded.some(word=>(r.title+' '+r.short+' '+r.items.join(' ')+' '+r.ingredients.join(' ')).toLowerCase().includes(word)));let caution='';if(profile==='diabetes')caution='Фильтр не рассчитывает углеводы и не подтверждает пригодность блюда при диабете. Сверь состав, порцию и личный план питания со специалистом.';if(profile==='gi')caution='При заболеваниях ЖКТ нет универсального списка подходящих блюд. Оценивай личную переносимость и рекомендации лечащего специалиста.';if(profile==='lactose')caution='Проверяй маркировку: в готовых продуктах могут быть молочные компоненты и следы аллергенов.';if(profile==='gluten')caution='Проверяй маркировку и возможные следы глютена; этот сайт не проверяет производство и перекрёстное загрязнение.';if(profile==='vegetarian')caution='Проверяй состав готовых соусов и других упакованных продуктов.';if(profile==='vegan')caution='Растительный фильтр ориентировочный: проверяй состав, включая соусы, и учитывай потребности в B12, белке и других нутриентах.';const out=$('#recommend-result');if(!out)return;if(!pool.length){out.innerHTML='<div class="recommend-empty"><strong>Не нашёл совпадений.</strong><p>Увеличь время, отключи бюджетный фильтр или измени список исключённых продуктов.</p></div>';return;}let ranked=pool.map(r=>({r,score:(profile==='diabetes'?Number(r.fiber)+Number(r.simple):profile==='gi'?Number(r.simple)*2:0)+(budget&&r.cheap?1:0)+(kitchen==='no-cook'&&r.noCook?1:0)})).sort((a,b)=>b.score-a.score);const top=ranked.filter(x=>x.score===ranked[0].score).map(x=>x.r);const picked=top[Math.floor(Math.random()*top.length)];out.innerHTML=`<div class="recommend-picked"><div><span class="mini-label">ТВОЙ ВАРИАНТ · ${picked.time} МИН</span><h3>${safeText(picked.title)}</h3><p>${safeText(picked.short)}</p><div class="recommend-tags"><span>${categoryLabels[picked.kind]}</span><span>${picked.cheap?'Бюджетно':'Простые продукты'}</span><span>${picked.noCook?'Без готовки':picked.time+' минут'}</span></div></div><button class="btn btn-dark" id="open-picked" data-picked="${picked.id}">ОТКРЫТЬ РЕЦЕПТ ↗</button></div>${caution?'<p class="recommend-caution">'+safeText(caution)+'</p>':''}`;$('#open-picked').addEventListener('click',e=>openRecipe(e.currentTarget.dataset.picked));}
$('#recommend-button')?.addEventListener('click',chooseRecipe);$('#recommend-again')?.addEventListener('click',chooseRecipe);

// Habits.
$$('[data-habit]').forEach(box=>{const state=read(STORE.habits,{});box.checked=!!state[box.dataset.habit];box.addEventListener('change',()=>{const next=read(STORE.habits,{});next[box.dataset.habit]=box.checked;write(STORE.habits,next)})});

// Weekly planner: each slot points to a real recipe card, with a visible summary.
const dayNames=['ПОНЕДЕЛЬНИК','ВТОРНИК','СРЕДА','ЧЕТВЕРГ','ПЯТНИЦА','СУББОТА','ВОСКРЕСЕНЬЕ'];
const mealSlots=[
  {label:'Завтрак',kinds:['breakfast']},
  {label:'Обед',kinds:['main']},
  {label:'Ужин',kinds:['main','snack']}
];
const recipesForSlot=slot=>recipes.filter(r=>slot.kinds.includes(r.kind));
const defaultMenu=()=>dayNames.map((_,day)=>mealSlots.map((slot,mi)=>{const pool=recipesForSlot(slot);return pool[(day*2+mi*3)%pool.length].id}));
let menuState=read(STORE.menu,null);
if(!Array.isArray(menuState)||menuState.length!==7||menuState.some(row=>!Array.isArray(row)||row.length!==3))menuState=defaultMenu();
else menuState=menuState.map((row,di)=>row.map((id,mi)=>recipesForSlot(mealSlots[mi]).some(r=>r.id===id)?id:defaultMenu()[di][mi]));
const mealPlan=$('#meal-plan');
function recipeForMenu(id){return recipes.find(r=>r.id===id)||recipes[0]}
function renderMenu(){
  if(!mealPlan)return;
  mealPlan.innerHTML=dayNames.map((day,di)=>`<article class="day-card"><h3><span class="day-name">${day}</span><span class="day-count">${String(di+1).padStart(2,'0')} / 07</span></h3>${mealSlots.map((slot,mi)=>{
    const options=recipesForSlot(slot),picked=recipeForMenu(menuState[di][mi]);
    return `<div class="meal-row"><label for="meal-${di}-${mi}">${slot.label}</label><div class="meal-field"><select class="meal-select" id="meal-${di}-${mi}" data-day="${di}" data-meal="${mi}" aria-label="${slot.label}, ${day}">${options.map(r=>`<option value="${r.id}" ${picked.id===r.id?'selected':''}>${safeText(r.title)}</option>`).join('')}</select><div class="meal-detail"><div class="meal-detail-top"><strong>${safeText(picked.title)}</strong><span>${picked.time} мин</span></div><p>${safeText(picked.short)}</p><div class="meal-tags"><span>${picked.cheap?'Бюджетно':'Простые продукты'}</span><span>${picked.noCook?'Без плиты':'Нужно приготовить'}</span></div></div></div></div>`;
  }).join('')}</article>`).join('');
  $$('select[data-day]',mealPlan).forEach(sel=>sel.addEventListener('change',()=>{menuState[+sel.dataset.day][+sel.dataset.meal]=sel.value;write(STORE.menu,menuState);renderMenu();renderShopping()}));
}
const shoppingList=$('#shopping-list');
function renderShopping(){
  if(!shoppingList)return;
  const saved=read(STORE.shopping,{}),counts=new Map();
  menuState.flat().map(recipeForMenu).forEach(recipe=>recipe.items.forEach(item=>counts.set(item,(counts.get(item)||0)+1)));
  const entries=[...counts.entries()].sort((a,b)=>a[0].localeCompare(b[0],'ru'));
  if(!entries.length){shoppingList.innerHTML='<p class="shopping-empty">Выбери блюда в плане — здесь появятся продукты.</p>';updateShoppingCounter();return;}
  shoppingList.innerHTML=entries.map(([item,count])=>`<label class="shopping-item ${saved[item]?'checked':''}"><input type="checkbox" data-shopping="${safeText(item)}" ${saved[item]?'checked':''}><span>${safeText(item)}<small>${count>1?`Нужно для ${count} блюд`:'Для выбранного блюда'}</small></span></label>`).join('');
  $$('[data-shopping]',shoppingList).forEach(cb=>cb.addEventListener('change',()=>{const obj=read(STORE.shopping,{});obj[cb.dataset.shopping]=cb.checked;write(STORE.shopping,obj);cb.closest('.shopping-item').classList.toggle('checked',cb.checked);updateShoppingCounter()}));
  updateShoppingCounter();
}
function updateShoppingCounter(){if(!shoppingList)return;const all=$$('[data-shopping]',shoppingList),checked=all.filter(x=>x.checked).length;const c=$('#shopping-counter');if(c)c.textContent=`${checked} / ${all.length}`;const b=$('#profile-shopping');if(b)b.textContent=checked}
if(mealPlan){
  write(STORE.menu,menuState);renderMenu();renderShopping();
  const budgetInput=$('#budget'),kitchenInput=$('#kitchen');
  if(budgetInput){budgetInput.value=read(STORE.budget,2500);budgetInput.addEventListener('change',()=>write(STORE.budget,budgetInput.value))}
  if(kitchenInput){kitchenInput.value=read(STORE.kitchen,'full');kitchenInput.addEventListener('change',()=>{write(STORE.kitchen,kitchenInput.value);if(kitchenInput.value==='minimal')document.querySelector('.aside-note')?.scrollIntoView({behavior:'smooth',block:'nearest'})})}
  $('#clear-menu')?.addEventListener('click',()=>{menuState=defaultMenu();write(STORE.menu,menuState);renderMenu();renderShopping()});
  $('#uncheck-all')?.addEventListener('click',()=>{const obj=read(STORE.shopping,{});Object.keys(obj).forEach(k=>obj[k]=false);write(STORE.shopping,obj);renderShopping()});
  $('#copy-list')?.addEventListener('click',async()=>{const items=$$('[data-shopping]',shoppingList).filter(x=>!x.checked).map(x=>'[ ] '+x.dataset.shopping);await copyText('СПИСОК ПОКУПОК — Тарелка\n'+items.join('\n'));$('#copy-list').textContent='СКОПИРОВАНО ✓';setTimeout(()=>$('#copy-list').textContent='Скопировать список ↗',1500)});
  $('#add-plan-to-basket')?.addEventListener('click',()=>{const items=$$('[data-shopping]',shoppingList).filter(x=>!x.checked).map(x=>x.dataset.shopping);addToBasket(items);location.href='basket.html'});
}

// Shopping basket stored only in this browser; not connected to a retailer account.
const basketItems=$('#basket-items');
function renderBasket(){if(!basketItems)return;const b=read(STORE.basket,{}),entries=Object.entries(b);const empty=$('#basket-empty');if(empty)empty.hidden=entries.length>0;basketItems.innerHTML=entries.map(([name,item])=>`<div class="basket-row ${item.checked?'is-checked':''}"><label class="basket-check"><input type="checkbox" data-basket-check="${safeText(name)}" ${item.checked?'checked':''}><span></span></label><div class="basket-name">${safeText(name)}</div><div class="basket-qty"><button type="button" data-qty="-" data-item="${safeText(name)}" aria-label="Уменьшить">−</button><span>${Number(item.qty)||1}</span><button type="button" data-qty="+" data-item="${safeText(name)}" aria-label="Увеличить">＋</button></div><button type="button" class="basket-remove" data-remove="${safeText(name)}" aria-label="Удалить">×</button></div>`).join('');const count=$('#basket-counter');if(count)count.textContent=`${entries.length} позиций · ${entries.filter(([,v])=>v.checked).length} отмечено`;$$('[data-basket-check]',basketItems).forEach(el=>el.addEventListener('change',()=>{const obj=read(STORE.basket,{});obj[el.dataset.basketCheck].checked=el.checked;write(STORE.basket,obj);renderBasket()}));$$('[data-qty]',basketItems).forEach(el=>el.addEventListener('click',()=>{const obj=read(STORE.basket,{}),item=obj[el.dataset.item];item.qty=Math.max(1,Math.min(99,(Number(item.qty)||1)+(el.dataset.qty==='+'?1:-1)));write(STORE.basket,obj);renderBasket()}));$$('[data-remove]',basketItems).forEach(el=>el.addEventListener('click',()=>{const obj=read(STORE.basket,{});delete obj[el.dataset.remove];write(STORE.basket,obj);renderBasket();updateBasketBadge()}));updateBasketBadge()}
async function copyText(textOut){try{await navigator.clipboard.writeText(textOut)}catch(e){const ta=document.createElement('textarea');ta.value=textOut;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}}
if(basketItems){renderBasket();$('#basket-clear')?.addEventListener('click',()=>{if(confirm('Очистить список покупок?')){write(STORE.basket,{});renderBasket()}});$('#basket-uncheck')?.addEventListener('click',()=>{const obj=read(STORE.basket,{});Object.values(obj).forEach(v=>v.checked=false);write(STORE.basket,obj);renderBasket()});$('#basket-copy')?.addEventListener('click',async()=>{const obj=read(STORE.basket,{});const lines=Object.entries(obj).filter(([,v])=>!v.checked).map(([name,v])=>`[ ] ${name} — ${v.qty} шт.`);await copyText('СПИСОК ПОКУПОК — Тарелка\n'+lines.join('\n'));$('#basket-copy').textContent='СКОПИРОВАНО ✓';setTimeout(()=>$('#basket-copy').textContent='Скопировать список ↗',1500)})}
updateBasketBadge();

// Three short knowledge quizzes.
