// Games and everyday tools: all progress is local to this browser.
const LAB={progress:'tarelka_lab_progress_v1',fridge:'tarelka_fridge_v1',calendar:'tarelka_calendar_v1',budget:'tarelka_budget_game_v1'};
function labProgress(){return read(LAB.progress,{})}
function finishLab(key,points=10){const p=labProgress();if(!p[key]){p[key]={done:true,points,at:new Date().toISOString()};write(LAB.progress,p)}renderLabSummary()}
function renderLabSummary(){const p=labProgress(),keys=['plate','myth','memory','budget','fridge','label','calendar','quiz'];const count=keys.filter(k=>p[k]?.done).length;const points=Object.values(p).reduce((n,v)=>n+(Number(v.points)||0),0);const pointEl=$('#lab-points'),progressEl=$('#lab-progress');if(pointEl)pointEl.textContent=points;if(progressEl)progressEl.textContent=`${count} из 8 активностей`;$$('[data-game-status]').forEach(el=>{if(p[el.dataset.gameStatus]?.done)el.textContent='ПРОЙДЕНО ✓'});const achievements=$('#achievement-grid');if(achievements){const defs=[['📝','Первый тест','Пройди любой тест из раздела «Тесты»',!!p.quiz],['🥗','Собрал тарелку','Пройди игру «Собери тарелку»',!!p.plate],['💡','Развенчатель мифов','Ответь на вопросы игры «Миф или правда?»',!!p.myth],['🧠','Память на продукты','Найди все пары',!!p.memory],['🛒','Планировщик покупок','Собери студенческую корзину',!!p.budget],['🏠','Запасы под рукой','Добавь продукты в холодильник',!!p.fridge],['🔎','Внимательный читатель','Разбери состав продукта',!!p.label],['📅','Своя история','Добавь запись в календарь',!!p.calendar]];achievements.innerHTML=defs.map(([emoji,title,desc,ok])=>`<article class="achievement ${ok?'unlocked':''}"><span>${emoji}</span><div><strong>${title}</strong><small>${desc}</small></div><b>${ok?'ОТКРЫТО':'ЗАКРЫТО'}</b></article>`).join('')}}
renderLabSummary();

// 1. Build a balanced plate: classify familiar foods by broad food group.
if($('#plate-game')){
 const questions=[['🥦','Брокколи','plants'],['🥚','Яйцо','protein'],['🌾','Овсяные хлопья','grains'],['🍎','Яблоко','plants'],['🫘','Фасоль','protein'],['🍚','Рис','grains']];let pi=0,ps=0,plocked=false;
 const showPlate=()=>{const q=questions[pi];$('#plate-round').textContent=`ПРОДУКТ ${pi+1} / ${questions.length}`;$('#plate-score').textContent=`${ps} правильных`;$('#plate-emoji').textContent=q[0];$('#plate-product').textContent=q[1];$('#plate-feedback').textContent='Выбери категорию.';$$('[data-category]').forEach(b=>b.disabled=false);plocked=false};
 $$('[data-category]').forEach(b=>b.addEventListener('click',()=>{if(plocked)return;plocked=true;const good=b.dataset.category===questions[pi][2];if(good)ps++;$('#plate-feedback').textContent=good?'Верно! Хорошее попадание.':'Не совсем. Подумай, к какой группе относится продукт.';$('#plate-score').textContent=`${ps} правильных`;$$('[data-category]').forEach(x=>x.disabled=true);if(pi<questions.length-1){const next=document.createElement('button');next.className='btn btn-acid lab-next';next.textContent='СЛЕДУЮЩИЙ ПРОДУКТ →';next.onclick=()=>{next.remove();pi++;showPlate()};$('#plate-feedback').after(next)}else{const next=document.createElement('button');next.className='btn btn-acid lab-next';next.textContent=`РЕЗУЛЬТАТ: ${ps} / ${questions.length} · ЕЩЁ РАЗ ↻`;next.onclick=()=>{next.remove();finishLab('plate',ps*2);pi=0;ps=0;showPlate()};$('#plate-feedback').after(next);finishLab('plate',ps*2)}}));$('#plate-restart').addEventListener('click',()=>{pi=0;ps=0;$$('.lab-next').forEach(x=>x.remove());showPlate()});showPlate();
}
// 2. Myth or fact.
if($('#myth-game')){const qs=[['Замороженные овощи могут быть частью разнообразного рациона.',true,'Да. Заморозка помогает хранить овощи; смотри состав и способ приготовления.'],['Состав продукта полезно читать каждый раз, даже если упаковка знакомая.',true,'Рецептура может измениться — проверяй актуальную упаковку.'],['Если продукт дорогой, он обязательно полезнее дешёвого аналога.',false,'Цена сама по себе не определяет питательную ценность.'],['Готовую еду можно оставлять при комнатной температуре на весь день.',false,'Скоропортящиеся блюда важно своевременно убирать на хранение по рекомендациям.'],['Один продукт сам по себе не делает весь рацион «правильным» или «неправильным».',true,'Важнее общий контекст питания и разнообразие.']];let i=0,score=0,locked=false;
 const draw=()=>{$('#myth-round').textContent=`ВОПРОС ${i+1} / ${qs.length}`;$('#myth-score').textContent=`${score} очков`;$('#myth-statement').textContent=qs[i][0];$('#myth-feedback').textContent='Выбери ответ.';$$('[data-myth]').forEach(b=>b.disabled=false);locked=false};
 $$('[data-myth]').forEach(b=>b.addEventListener('click',()=>{if(locked)return;locked=true;const correct=(b.dataset.myth==='true')===qs[i][1];if(correct)score++;$('#myth-feedback').textContent=(correct?'Верно! ':'Не совсем. ')+qs[i][2];$('#myth-score').textContent=`${score} очков`;$$('[data-myth]').forEach(x=>x.disabled=true);const next=document.createElement('button');next.className='btn btn-acid lab-next';next.textContent=i===qs.length-1?'ЗАВЕРШИТЬ ↗':'СЛЕДУЮЩИЙ ВОПРОС →';next.onclick=()=>{next.remove();if(i<qs.length-1){i++;draw()}else{$('#myth-feedback').textContent=`Готово! Правильных ответов: ${score} из ${qs.length}.`;finishLab('myth',score*2);i=0;score=0;draw()}};$('#myth-feedback').after(next)}));$('#myth-restart').addEventListener('click',()=>{i=0;score=0;$$('.lab-next').forEach(x=>x.remove());draw()});draw()}
// 3. Memory matching.
if($('#memory-grid')){const pairs=[['🥕','Морковь'],['🥚','Яйцо'],['🍞','Хлеб'],['🫘','Фасоль']];let cards=[],opened=[],matched=new Set(),moves=0,busy=false;const drawMemory=()=>{cards=pairs.flatMap((p,i)=>[{id:i,face:p[0],label:p[1],kind:'food'},{id:i,face:['ОВОЩ','БЕЛОК','ЗЕРНО','БЕЛОК'][i],label:p[1],kind:'group'}]).sort(()=>Math.random()-.5);opened=[];matched=new Set();moves=0;busy=false;renderMemory()};const renderMemory=()=>{$('#memory-grid').innerHTML=cards.map((c,i)=>`<button class="memory-card ${opened.includes(i)||matched.has(c.id)?'revealed':''} ${matched.has(c.id)?'matched':''}" data-memory="${i}" ${matched.has(c.id)?'disabled':''}><span>${opened.includes(i)||matched.has(c.id)?safeText(c.kind==='food'?c.face:c.face):'?'}</span><small>${opened.includes(i)||matched.has(c.id)?safeText(c.kind==='food'?c.label:'ГРУППА'): 'ОТКРЫТЬ'}</small></button>`).join('');$('#memory-moves').textContent=`ХОДЫ: ${moves}`;$('#memory-found').textContent=`ПАРЫ: ${matched.size} / 4`;$$('[data-memory]').forEach(b=>b.addEventListener('click',()=>{const idx=+b.dataset.memory;if(busy||opened.includes(idx)||matched.has(cards[idx].id))return;opened.push(idx);renderMemory();if(opened.length===2){moves++;const [a,b]=opened.map(x=>cards[x]);if(a.id===b.id&&a.kind!==b.kind){matched.add(a.id);opened=[];renderMemory();$('#memory-feedback').textContent='Есть пара!';if(matched.size===4){$('#memory-feedback').textContent=`Все пары найдены за ${moves} ходов!`;finishLab('memory',Math.max(5,24-moves))}}else{busy=true;$('#memory-feedback').textContent='Не совпало — попробуй ещё.';setTimeout(()=>{opened=[];busy=false;renderMemory()},850)}}}))};$('#memory-restart').addEventListener('click',drawMemory);drawMemory()}
// 4. Budget basket challenge. The sample prices are fictional game values.
if($('#budget-items')){const stock=[['Овсянка',2,'grains'],['Гречка',3,'grains'],['Яблоки',2,'plants'],['Морковь',1,'plants'],['Замороженные овощи',3,'plants'],['Яйца',3,'protein'],['Фасоль',2,'protein'],['Йогурт',2,'other'],['Хлеб',2,'grains'],['Рыба',5,'protein']];let selected=new Set();const drawBudget=()=>{$('#budget-items').innerHTML=stock.map(([name,price,group],i)=>`<label class="budget-item"><input type="checkbox" data-budget="${i}" ${selected.has(i)?'checked':''}><span>${safeText(name)}<small>${group==='plants'?'ОВОЩИ / ФРУКТЫ':group==='protein'?'БЕЛОК':group==='grains'?'ЗЕРНОВЫЕ':'ДРУГОЕ'}</small></span><b>€ ${price}</b></label>`).join('');const total=[...selected].reduce((s,i)=>s+stock[i][1],0);$('#budget-total').textContent=`€ ${total}`;$('#budget-meter-fill').style.width=Math.min(100,total/20*100)+'%';$$('[data-budget]').forEach(x=>x.addEventListener('change',()=>{const i=+x.dataset.budget;if(x.checked)selected.add(i);else selected.delete(i);drawBudget()}))};$('#budget-check').addEventListener('click',()=>{const total=[...selected].reduce((s,i)=>s+stock[i][1],0),groups=new Set([...selected].map(i=>stock[i][2]));if(total>20){$('#budget-feedback').textContent='Пока выше условного бюджета. Попробуй заменить несколько позиций.'}else if(selected.size<4||groups.size<3){$('#budget-feedback').textContent='Добавь ещё несколько продуктов и попробуй выбрать позиции из разных групп.'}else{$('#budget-feedback').textContent=`Получилось! ${selected.size} позиций на условные € ${total}. Разнообразие — хорошее начало.`;finishLab('budget',15)}});$('#budget-reset').addEventListener('click',()=>{selected.clear();drawBudget();$('#budget-feedback').textContent='Корзина очищена.'});drawBudget()}
// 5. Fridge inventory and recipe matching against the existing recipe catalogue.
if($('#fridge-form')){let fridge=read(LAB.fridge,[]);const renderFridge=()=>{$('#fridge-list').innerHTML=fridge.map((x,i)=>`<button class="tag-chip" data-fridge-remove="${i}" type="button">${safeText(x)} ×</button>`).join('');$$('[data-fridge-remove]').forEach(b=>b.addEventListener('click',()=>{fridge.splice(+b.dataset.fridgeRemove,1);write(LAB.fridge,fridge);renderFridge()}));const matches=recipes.map(r=>({...r,matched:(r.items||[]).filter(item=>fridge.some(f=>item.toLowerCase().includes(f.toLowerCase())||f.toLowerCase().includes(item.toLowerCase().split(' ')[0]))).length})).filter(r=>r.matched>0).sort((a,b)=>b.matched-a.matched).slice(0,5);$('#fridge-results').innerHTML=matches.length?`<h3>МОЖНО ПРИГОТОВИТЬ</h3>`+matches.map(r=>`<article class="tool-result"><div><strong>${safeText(r.title)}</strong><small>Совпадений: ${r.matched} · ${r.time} мин</small></div><a href="recipes.html">К РЕЦЕПТАМ ↗</a></article>`).join(''):'<p class="muted-copy">Добавь продукты, чтобы найти совпадения с каталогом рецептов.</p>'};$('#fridge-form').addEventListener('submit',e=>{e.preventDefault();const input=$('#fridge-input'),value=input.value.trim();if(!value)return;value.split(',').map(x=>x.trim()).filter(Boolean).forEach(x=>{if(!fridge.some(y=>y.toLowerCase()===x.toLowerCase()))fridge.push(x)});fridge=fridge.slice(0,30);input.value='';write(LAB.fridge,fridge);if(fridge.length)finishLab('fridge',5);renderFridge()});renderFridge()}
// 6. Ingredient label explainer. It flags common allergens and selected E-number groups only.
if($('#label-analyze')){$('#label-analyze').addEventListener('click',()=>{const raw=$('#label-input').value.trim();if(!raw){$('#label-results').innerHTML='<p class="muted-copy">Сначала вставь список ингредиентов с упаковки.</p>';return}const text=raw.toLowerCase(),allergens=[['молоко / молочные продукты',['молоко','лактоз','сыворот','казеин','сливк']],['глютенсодержащие злаки',['пшениц','рожь','ячмен','глютен','спельт']],['соя',['соя','соев']],['арахис и орехи',['арахис','миндал','фундук','грецк','орех']],['яйцо',['яйц','альбумин']],['рыба / морепродукты',['рыб','кревет','ракообраз']]];const found=allergens.filter(([name,terms])=>terms.some(t=>text.includes(t))).map(x=>x[0]);const es=[...new Set((raw.match(/\bE\s?\d{3,4}[a-z]?\b/gi)||[]).map(x=>x.toUpperCase().replace(/\s/g,'')))];const explanations=es.map(e=>`${e} — код пищевой добавки; по одному коду нельзя сделать вывод о безопасности или вреде`).slice(0,8);$('#label-results').innerHTML=`<div class="label-summary"><strong>${found.length?'Возможные совпадения с аллергенами':'Явных совпадений по словарю не найдено'}</strong><p>${found.length?safeText(found.join(' · ')):'Автоматическая проверка не гарантирует отсутствия аллергенов — сверяй полный состав и предупреждения.'}</p></div>${explanations.length?`<div class="label-summary"><strong>Обозначения добавок</strong><p>${explanations.map(safeText).join('<br>')}</p></div>`:''}<p class="muted-copy">Это простой поиск слов, а не полноценная проверка состава. Производитель может использовать другие названия; при аллергии всегда сверяй маркировку и рекомендации врача.</p>`;finishLab('label',5)})}
// 7. Food calendar: optional meal notes, no calorie or weight tracking.
if($('#calendar-form')){const today=new Date();$('#calendar-date').value=`${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}-${String(today.getDate()).padStart(2,'0')}`;let entries=read(LAB.calendar,[]);const renderCalendar=()=>{$('#calendar-list').innerHTML=entries.length?'<h3>ПОСЛЕДНИЕ ЗАПИСИ</h3>'+entries.slice().sort((a,b)=>b.date.localeCompare(a.date)).map((x,i)=>`<article class="calendar-entry"><time>${safeText(x.date)}</time><span>${safeText(x.kind)}</span><strong>${safeText(x.dish)}</strong><button type="button" data-calendar-remove="${i}" aria-label="Удалить запись">×</button></article>`).join(''):'<p class="muted-copy">Пока нет записей. Добавь первую, когда захочешь.</p>';$$('[data-calendar-remove]').forEach(b=>b.addEventListener('click',()=>{const sorted=entries.slice().sort((a,b)=>b.date.localeCompare(a.date));const target=sorted[+b.dataset.calendarRemove];entries=entries.filter(x=>x!==target);write(LAB.calendar,entries);renderCalendar()}))};$('#calendar-form').addEventListener('submit',e=>{e.preventDefault();const date=$('#calendar-date').value,kind=$('#calendar-kind').value,dish=$('#calendar-dish').value.trim();if(!date||!dish)return;entries.push({date,kind,dish});entries=entries.slice(-100);write(LAB.calendar,entries);$('#calendar-dish').value='';finishLab('calendar',5);renderCalendar()});renderCalendar()}
